-- AG Systems Map — run once in Supabase → SQL Editor → New query → Run

create table if not exists public.maps (
  id text primary key,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

alter table public.maps enable row level security;

-- Anyone with the site link can read and edit (same as the old shared artifact).
drop policy if exists "maps read" on public.maps;
drop policy if exists "maps write" on public.maps;
create policy "maps read"  on public.maps for select to anon, authenticated using (true);
create policy "maps write" on public.maps for all    to anon, authenticated using (true) with check (true);

-- Live updates so everyone sees ticks instantly
do $$ begin
  alter publication supabase_realtime add table public.maps;
exception when duplicate_object then null; end $$;

-- Your current saved maps (template + Abarca Nov 2026)
insert into public.maps (id, data) values
  ('template', $json${"name": "Template", "kind": "template", "package": null, "rev": 1, "people": [{"id": "andres", "name": "Andres", "role": "Sales, strategy, growth"}, {"id": "esteban", "name": "Esteban", "role": "Client comms, shooting, ops"}, {"id": "isabella", "name": "Isabella", "role": "PM, planning, QC"}, {"id": "shooter", "name": "Shooter", "role": "On-site capture"}, {"id": "editor", "name": "Editor", "role": "Video edits"}, {"id": "setter", "name": "Setter", "role": "Calls and books leads"}, {"id": "client", "name": "Client", "role": "Approvals, outcomes"}], "packages": [{"id": "visible", "name": "Visible", "price": "$1,500/mo", "blurb": "~6 reels + 6 posts, social management, booking page, review texts.", "systems": ["sys1", "sys2", "sys3"]}, {"id": "authority", "name": "Authority", "price": "$2,500/mo", "blurb": "10 reels, 8 posts, daily stories, local boosting of top content.", "systems": ["sys1", "sys2", "sys3", "sys4"]}, {"id": "growth", "name": "Growth", "price": "$3,500/mo + $125/appt", "blurb": "Authority + 10 ads, testing, appointment setting, 15-day reports.", "systems": ["sys1", "sys2", "sys3", "sys4", "sys5", "sys6"]}], "systems": [{"id": "sys1", "code": "1", "name": "Content & strategy", "short": "From data to approved, ready-to-post content.", "cadence": "Monthly rolling cycle", "stages": [{"id": "st1a", "name": "Strategy & ideas", "when": "Week 4 of M-2", "steps": [{"id": "s-perf", "title": "Pull last month's performance", "short": "Top and bottom posts, hold rate, saves, leads per retainer.", "detail": "On the 1st, a scheduled Claude task reads Metricool and Notion, then writes a Performance Report page on each retainer: top 3 and bottom 3 posts, 3-second hold, saves, shares, profile visits and leads. Isabella reviews it. This runs first because every later step depends on it.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task + Metricool + Notion", "when": "1st of each month", "feeds": ["s-strategy"]}, {"id": "s-industry", "title": "Industry and competitor scan", "short": "What's going viral in the niche and where competitors are weak.", "detail": "A monthly scheduled run looks at competitors and viral content in the retainer's industry, scores outliers, and lists strengths and weaknesses next to the retainer's own results. Output is saved to the retainer page.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task (web search) or Muse", "when": "Monthly, week 4", "feeds": ["s-strategy"]}, {"id": "s-persona", "title": "Persona and pain points", "short": "Who buys, what hurts, which words they use.", "detail": "Research the target persona, pain points, objections and the exact words customers use. Sources: the client's Google reviews, competitor reviews, Reddit, and Esteban's call notes. Done at onboarding, then refreshed quarterly. Andres approves.", "mode": "hybrid", "owner": "isabella", "tool": "Claude", "when": "Onboarding + quarterly", "feeds": []}, {"id": "s-guidelines", "title": "Brand guidelines", "short": "Video, static, story, caption tone and ad rules per retainer.", "detail": "One guideline page per retainer covering video style, statics, stories, the caption tone prompt, ad rules, and do's and don'ts. It's loaded as knowledge in the retainer's Claude Project so every AI step uses it automatically. Refreshed on the quarterly refresh day.", "mode": "manual", "owner": "isabella", "tool": "Notion + Claude Project", "when": "Quarterly", "feeds": []}, {"id": "s-hooks", "title": "Update the Hook Bank", "short": "Add trending hooks and tag which ones performed.", "detail": "A Notion database of hooks with format, industry, source, times used and average 3-second hold. A monthly Claude task adds 20 trending hooks, and Metricool data marks which hooks actually worked for your accounts.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task + Metricool", "when": "Monthly", "feeds": []}, {"id": "s-structures", "title": "Video structure library", "short": "Templates: before/after, job walk, myth vs fact, POV, offer.", "detail": "Keep a library of proven video structures with reference links. Refresh it on the same quarterly day as the guidelines.", "mode": "manual", "owner": "isabella", "tool": "Notion", "when": "Quarterly", "feeds": []}, {"id": "s-field", "title": "Field ideas from real jobs", "short": "10 grounded ideas per retainer from jobs and client questions.", "detail": "Isabella and Esteban log ideas from real jobs, client FAQs and things heard on site through a Notion form on the phone. Entries land straight in the Idea Bank.", "mode": "hybrid", "owner": "isabella", "tool": "Notion form", "when": "Ongoing", "feeds": []}, {"id": "s-strategy", "title": "Monthly strategy (1 page)", "short": "Sales goal, pillar mix, what to double down on and cut.", "detail": "Claude drafts one page per retainer: the month's sales goal, pillar mix, what to double down on and what to cut, the offer to push, and ad tests. Andres approves in the Monday founder meeting, about 5 minutes per retainer.", "mode": "hybrid", "owner": "andres", "tool": "Claude skill: monthly-plan", "when": "Monthly, week 4", "feeds": ["s-ideas"]}, {"id": "s-ideas", "title": "Generate 40 ideas", "short": "Each tagged with pillar, format, hook, sales job and CTA.", "detail": "The retainer's Claude Project uses the guidelines, reports and Hook Bank as context to produce 40 ideas. Each one is tagged with pillar, format, hook, sales job, CTA and shoot needs. One generator only; other AI tools are optional critics.", "mode": "auto", "owner": "isabella", "tool": "Claude Project (per retainer)", "when": "Monthly, week 4", "feeds": []}, {"id": "s-score", "title": "Score and keep the top 25", "short": "Rubric: hook, sales intent, persona fit, shootable, not repeated.", "detail": "Claude scores every idea from 1 to 5 on hook strength, sales intent, persona fit, whether it can be shot in one 3-hour shoot, and whether it repeats the last 90 days. The top 25 are kept.", "mode": "auto", "owner": "isabella", "tool": "Claude Project", "when": "Monthly, week 4", "feeds": []}, {"id": "s-pick", "title": "Final pick", "short": "Tier count + 3 backups. The rest go to the Idea Bank.", "detail": "Isabella picks the final pieces: Visible ~12, Authority 18, Growth 18 plus 10 ads, and 3 backups each. Unused ideas are saved in the searchable Idea Bank database, not a Drive folder.", "mode": "manual", "owner": "isabella", "tool": "Notion Idea Bank", "when": "Monthly, week 4", "feeds": ["p-scripts"]}]}, {"id": "st1b", "name": "Planning", "when": "Week 4 of M-2", "steps": [{"id": "p-scripts", "title": "Scripts and shot lists", "short": "Hook line, beats, B-roll, who's on camera, CTA.", "detail": "Claude drafts a script and shot list for every piece in one run and writes it into each Notion item. Isabella edits.", "mode": "hybrid", "owner": "isabella", "tool": "Claude Project", "when": "Week 4 of M-2", "feeds": []}, {"id": "p-stories", "title": "Story plan", "short": "One theme per weekday plus a story capture list.", "detail": "Example frame: Mon crew, Tue job progress, Wed FAQ, Thu review, Fri offer. Ask the client's crew for 3 phone clips a week through an upload link.", "mode": "manual", "owner": "isabella", "tool": "Notion", "when": "Week 4 of M-2", "feeds": []}, {"id": "p-props", "title": "Set Notion properties", "short": "Format, type, pillar, sales job, dates, links, status.", "detail": "A Notion template button fills defaults by tier. Every automation reads the same status flow: Idea, Scripted, Shoot booked, Shot, Editing, QC, Client review, Approved, Scheduled, Posted, Analyzed.", "mode": "auto", "owner": "isabella", "tool": "Notion template button", "when": "Week 4 of M-2", "feeds": []}, {"id": "p-captions", "title": "Captions in brand tone", "short": "One run fills every caption, with search keywords.", "detail": "The retainer's Claude Project already holds the tone prompt, so one run writes every caption plus keywords for Instagram search and Google Business posts. Isabella checks.", "mode": "hybrid", "owner": "isabella", "tool": "Claude Project", "when": "Week 4 of M-2", "feeds": []}, {"id": "p-calendar", "title": "Calendar and shoot days", "short": "Max 3 shoot days per retainer, shooter assigned, post dates.", "detail": "Isabella sets shoot days and post dates in the Notion calendar. Shoot dates sync to the shooter's Google Calendar automatically.", "mode": "hybrid", "owner": "isabella", "tool": "Notion + Zapier → Google Calendar", "when": "Week 4 of M-2", "feeds": ["c-invite"]}, {"id": "p-brief", "title": "Shoot Brief per shoot day", "short": "Every piece, shots, props, people, access, weather backup.", "detail": "A Claude skill reads every Notion item with that shoot date and builds one brief: pieces, shots, props, people, location, client contact, parking and access, plus a weather backup.", "mode": "auto", "owner": "isabella", "tool": "Claude skill + Notion", "when": "Week 4 of M-2", "feeds": []}, {"id": "p-folders", "title": "Create Drive folders", "short": "Retainer / Cycle / RAW and Deliverables / piece.", "detail": "When a piece hits Scripted, an automation creates its RAW and Deliverables folders in Drive and writes the links back to Notion.", "mode": "auto", "owner": "isabella", "tool": "Make or Zapier + Google Drive", "when": "On status: Scripted", "feeds": []}, {"id": "p-approve", "title": "Client approves the month plan", "short": "3 business days; silence counts as approval.", "detail": "Esteban sends the list and scripts through the weekly client briefing page. An automatic reminder goes out on day 2. This matches the contract: week 1 is plan approval.", "mode": "hybrid", "owner": "esteban", "tool": "Client briefing page + Zapier reminder", "when": "End of week 4", "feeds": []}]}, {"id": "st1c", "name": "Shooting", "when": "Week 1 of M-1", "steps": [{"id": "c-invite", "title": "Shooter gets the invite and brief", "short": "Calendar event with the Shoot Brief link attached.", "detail": "Created automatically from the planning calendar, with the Shoot Brief attached.", "mode": "auto", "owner": "shooter", "tool": "Google Calendar + Notion", "when": "On scheduling", "feeds": []}, {"id": "c-confirm", "title": "48-hour confirmation", "short": "Confirm time, access, who's on camera. Check the weather.", "detail": "An auto-text confirms time, site access, who's on camera and that the site is clean. Esteban handles replies and checks the weather for exterior shots.", "mode": "hybrid", "owner": "esteban", "tool": "QUO via Zapier + HubSpot contact", "when": "48 h before", "feeds": []}, {"id": "c-shoot", "title": "Shoot the pieces", "short": "Follow the brief order. 3 hook takes for every ad.", "detail": "Shoot in brief order. Every ad concept gets 3 different opening hooks. That's the cheapest A/B test there is.", "mode": "manual", "owner": "shooter", "tool": "Shoot Brief on phone", "when": "Week 1 of M-1", "feeds": []}, {"id": "c-broll", "title": "Capture the B-roll library", "short": "Crew, trucks, tools, drone, details, portraits.", "detail": "Ten seconds each of crew working, trucks, tools, drone and exterior shots, details, and team portraits. This fixes missing B-roll and feeds AI generation and ads later.", "mode": "manual", "owner": "shooter", "tool": "Checklist in Shoot Brief", "when": "Every shoot", "feeds": []}, {"id": "c-release", "title": "Releases and testimonials", "short": "Signed release for anyone on camera; 30-second testimonial.", "detail": "Get a signed release from any homeowner or crew member on camera. When the customer is happy, ask for a 30-second testimonial. Testimonial ads aren't allowed without consent.", "mode": "hybrid", "owner": "shooter", "tool": "Tally form with signature", "when": "Every shoot", "feeds": []}, {"id": "c-upload", "title": "Upload within 24 hours", "short": "Named files in RAW / piece; status flips to Shot.", "detail": "Upload to RAW / piece within 24 hours, named client_piece_take. A new file in the folder sets the Notion status to Shot automatically.", "mode": "hybrid", "owner": "shooter", "tool": "Google Drive + Zapier", "when": "Within 24 h", "feeds": []}, {"id": "c-cull", "title": "Culling and selects", "short": "Best takes plus a selects note for the editor.", "detail": "AI pre-selects the best takes from transcripts, and Isabella confirms and writes timestamps and the best hook take for the editor. This was the step eating whole founder days.", "mode": "hybrid", "owner": "isabella", "tool": "Claude skill + Descript transcripts", "when": "Within 48 h", "feeds": ["e-assign"]}]}, {"id": "st1d", "name": "Editing & QC", "when": "Week 2 of M-1, approved by day 15", "steps": [{"id": "e-assign", "title": "Auto-assign the editor", "short": "Triggered on Shot; style reference already set.", "detail": "When a piece hits Shot, the assigned editor is notified with the style reference and selects note. Editors never wait for direction.", "mode": "auto", "owner": "isabella", "tool": "Notion + Zapier notification", "when": "On status: Shot", "feeds": []}, {"id": "e-ai", "title": "AI edit lane", "short": "Captions, cut-downs, resizes and variants by AI.", "detail": "Simple formats go to AI tools: talking-head cuts, captions, cut-downs, ad resizes. Higgsfield handles B-roll and ad variants. Claude writes the edit notes from the guidelines.", "mode": "hybrid", "owner": "isabella", "tool": "Descript / CapCut / Submagic + Higgsfield", "when": "Week 2 of M-1", "feeds": []}, {"id": "e-edit", "title": "Editor cuts to the reference", "short": "Hero videos edited by a human to the style reference.", "detail": "Hero reels and anything needing taste are edited by a human editor against the reference video.", "mode": "manual", "owner": "editor", "tool": "CapCut / Premiere", "when": "Week 2 of M-1", "feeds": []}, {"id": "e-statics", "title": "Statics and carousels", "short": "Real shoot photo + Canva brand template first.", "detail": "Start from a real job photo and the brand's Canva template. Canva Bulk Create builds the month's carousels from Notion in one go. AI is only for backgrounds, composites and ad variants. Contractors sell trust, so real jobs win.", "mode": "hybrid", "owner": "isabella", "tool": "Canva Bulk Create + Higgsfield + Claude", "when": "Week 2 of M-1", "feeds": []}, {"id": "e-copy", "title": "Copy check", "short": "English, spelling, claims and CTA on every file.", "detail": "Claude checks every static, carousel, caption and subtitle for English, spelling, claims and the CTA before QC sees it.", "mode": "auto", "owner": "isabella", "tool": "Claude", "when": "Before QC", "feeds": []}, {"id": "e-qc", "title": "QC: 10-point checklist", "short": "Pass = 9/10. Founders spot-check 1 per retainer weekly.", "detail": "Hook in 1.5 s, matches reference, safe zones, captions, brand fonts and colors, audio, licensed music, CTA, length and ratio, no errors. Pass is 9/10. Claude pre-checks text; Isabella checks visuals.", "mode": "hybrid", "owner": "isabella", "tool": "Notion QC score + Claude pre-check", "when": "Week 2 of M-1", "feeds": []}, {"id": "e-client", "title": "Client review", "short": "One batch link, max 2 rounds, silence = approved.", "detail": "Esteban sends one link with the whole batch and asks for consolidated feedback. Reminder on day 2, auto-approve on day 4. Maximum 2 revision rounds, per the contract.", "mode": "hybrid", "owner": "esteban", "tool": "Client briefing page + Zapier", "when": "By day 15 of M-1", "feeds": ["m-schedule"]}, {"id": "e-revise", "title": "Batched revisions", "short": "Fixes done once a week, not as a daily drip.", "detail": "Revisions are batched once a week and the revision count is logged on the piece. The editor scorecard tracks it monthly.", "mode": "manual", "owner": "editor", "tool": "Notion", "when": "Weekly", "feeds": []}]}]}, {"id": "sys2", "code": "2", "name": "Social media management", "short": "Scheduling, Google Business, stories, comment-to-lead.", "cadence": "Daily automation", "stages": [{"id": "st2", "name": "Scheduling & publishing", "when": "Daily", "steps": [{"id": "m-schedule", "title": "Auto-schedule approved posts", "short": "At the best time per account; status flips to Scheduled.", "detail": "A daily Claude task finds every piece marked Approved, schedules it in Metricool at the best time for that account, flips Notion to Scheduled and saves the post ID.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task + Metricool + Notion", "when": "Daily", "feeds": []}, {"id": "m-posted", "title": "Mark as Posted", "short": "Closes the loop Metricool doesn't close itself.", "detail": "The same daily task checks Metricool and flips live posts to Posted in Notion.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task", "when": "Daily", "feeds": []}, {"id": "m-gbp", "title": "Google Business posts", "short": "1–2 a week: recent job, photo, service, city.", "detail": "Every plan includes Google Business Profile. Repurpose the week's best post as a GBP post.", "mode": "auto", "owner": "isabella", "tool": "Metricool (GBP)", "when": "Weekly", "feeds": []}, {"id": "m-stories", "title": "Daily stories", "short": "From the story plan and crew clips.", "detail": "Post daily stories from the story plan and the client crew's phone clips.", "mode": "hybrid", "owner": "isabella", "tool": "Metricool or native app", "when": "Daily", "feeds": []}, {"id": "m-dm", "title": "Comment-to-lead DMs", "short": "\"Comment ROOF\" → auto-DM with the booking link → HubSpot.", "detail": "AG doesn't answer client DMs, so automation catches buying intent: a keyword comment triggers a DM with the booking page, and the lead lands in HubSpot. The client still handles real conversations.", "mode": "auto", "owner": "isabella", "tool": "ManyChat + Zapier → HubSpot", "when": "Always on", "feeds": ["l-intake"]}, {"id": "m-results", "title": "Results back to Notion", "short": "7 days after posting, metrics fill the Results field.", "detail": "Metrics flow back to Notion automatically. They feed next month's strategy and Monday's boost candidates.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task (Metricool → Notion)", "when": "Post + 7 days", "feeds": ["s-perf", "b-candidates"]}, {"id": "m-report", "title": "Monthly client report", "short": "Sales first: leads, appointments, top posts and why.", "detail": "Claude drafts a sales-led report, Isabella checks it and Esteban sends it by the 1st.", "mode": "hybrid", "owner": "esteban", "tool": "Claude + Metricool + HubSpot", "when": "By the 1st", "feeds": []}]}]}, {"id": "sys3", "code": "3", "name": "Lead & reputation automation", "short": "Booking page, client number, reviews, lead intake.", "cadence": "Set up once, runs always", "stages": [{"id": "st3", "name": "Setup + always-on flows", "when": "Onboarding", "steps": [{"id": "l-gbp", "title": "Google Business Profile setup", "short": "Categories, services, areas, 20+ photos, Q&A, matching NAP.", "detail": "Manager access, then a full setup: categories, services, service areas, hours, 20+ real job photos, Q&A, and the same name, address and phone everywhere. This drives Google and AI search visibility.", "mode": "manual", "owner": "andres", "tool": "Google Business Profile", "when": "Onboarding", "feeds": []}, {"id": "l-page", "title": "Booking page", "short": "One offer, proof, short form with qualifying questions.", "detail": "Cloned from the template. Asks ZIP, homeowner yes/no, service and timeline. Hidden fields capture UTMs and the ad click ID. Includes an unchecked SMS consent box with clear wording.", "mode": "manual", "owner": "andres", "tool": "Own builder or HubSpot + Calendly", "when": "Onboarding", "feeds": []}, {"id": "l-number", "title": "Client's own QUO number", "short": "Registered under the client (A2P 10DLC); missed-call text-back on.", "detail": "Texts must come from a number registered to the client's business. Approval takes about 2–5 business days, so start in week 1. After setup, missed calls get an instant text with the booking link.", "mode": "hybrid", "owner": "andres", "tool": "QUO", "when": "Onboarding, then always on", "feeds": []}, {"id": "l-reviews", "title": "Review request after every job", "short": "Day 0 text with the Google link, one reminder on day 3.", "detail": "Triggered when a job is marked complete in the client's CRM. Clients with no CRM fill a 10-second Job Done form. Every customer gets the Google link; never only the happy ones.", "mode": "auto", "owner": "client", "tool": "Zapier + QUO (form fallback)", "when": "On job done", "feeds": []}, {"id": "l-replies", "title": "Reply to every Google review", "short": "Within 48 hours, drafted by Claude.", "detail": "A new review triggers a Claude draft reply, which Isabella approves and posts.", "mode": "hybrid", "owner": "isabella", "tool": "Zapier → Claude", "when": "Within 48 h", "feeds": []}, {"id": "l-intake", "title": "Lead intake", "short": "Form or DM → HubSpot → instant text → setter alert.", "detail": "Every lead source (form, Calendly, lead ad, ManyChat) creates a HubSpot contact tagged with client and source, sends an instant text from the client's number with the booking link, and alerts the setter to call within 5 minutes.", "mode": "auto", "owner": "setter", "tool": "Zapier + HubSpot + QUO", "when": "Instant", "feeds": ["a-alert"]}]}]}, {"id": "sys4", "code": "4", "name": "Boosting for local exposure", "short": "Rule-based boosts that build warm local audiences.", "cadence": "Weekly", "stages": [{"id": "st4", "name": "Weekly boost loop", "when": "Every Monday", "steps": [{"id": "b-candidates", "title": "List boost candidates", "short": "Top 25% hold rate and above-average share/save rate.", "detail": "Every Monday a Claude task lists posts from the last 14 days that clear the threshold into a Notion view.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task + Metricool", "when": "Every Monday", "feeds": []}, {"id": "b-pick", "title": "Pick 1–2 per client", "short": "Proof or trust pieces with a clear local tie only.", "detail": "Never boost pure entertainment, because it attracts viewers outside the service area.", "mode": "manual", "owner": "isabella", "tool": "Notion", "when": "Every Monday", "feeds": []}, {"id": "b-launch", "title": "Launch in Ads Manager", "short": "Engagement/video views, service area, pre-approved budget.", "detail": "Duplicate the saved template campaign. Not the Boost button. The budget was approved once in the contract, so there's no weekly asking.", "mode": "hybrid", "owner": "isabella", "tool": "Meta Ads Manager", "when": "Every Monday", "feeds": []}, {"id": "b-audience", "title": "Save viewers for retargeting", "short": "People who watched 50%+ become a warm audience.", "detail": "This is what turns boosting into leads: Growth ads retarget these warm local viewers.", "mode": "auto", "owner": "isabella", "tool": "Meta custom audiences", "when": "Always on", "feeds": ["ad-launch"]}, {"id": "b-track", "title": "Track boost results", "short": "Cost per 1,000 local reach, views, visits, later leads.", "detail": "Results feed the monthly report and prove the client's boost money is working.", "mode": "auto", "owner": "isabella", "tool": "Windsor.ai / Metricool", "when": "Monthly", "feeds": []}]}]}, {"id": "sys5", "code": "5", "name": "Ad creatives & A/B tests", "short": "Offer + diverse creative + real sales data back to Meta.", "cadence": "Monthly build, weekly review", "stages": [{"id": "st5", "name": "Ads loop", "when": "Monthly + weekly", "steps": [{"id": "ad-found", "title": "Foundations check", "short": "Offer, pixel + CAPI, Instant Forms, outcome stages, speed.", "detail": "No spend until all are green: an offer worth responding to, pixel and Conversions API, Instant Forms with qualifying questions, HubSpot outcome stages the client logs, and speed-to-lead under 5 minutes.", "mode": "manual", "owner": "andres", "tool": "Meta Events Manager + HubSpot", "when": "Onboarding", "feeds": []}, {"id": "ad-concepts", "title": "Choose ad concepts", "short": "Picked with the content plan; the same shoot captures them.", "detail": "Pick from the creative menu: direct-response, problem/solution, offer, testimonial, before/after, owner to camera, myth-buster, what to expect.", "mode": "hybrid", "owner": "isabella", "tool": "Claude Project + Notion", "when": "Week 4 of M-2", "feeds": []}, {"id": "ad-build", "title": "Build 10 ads", "short": "2 concepts × 3 hooks, 1 testimonial, 3 statics, all resized.", "detail": "Variants and resizes in 9:16, 4:5 and 1:1.", "mode": "hybrid", "owner": "editor", "tool": "Higgsfield + Canva + CapCut", "when": "Week 2 of M-1", "feeds": []}, {"id": "ad-launch", "title": "Launch the campaign", "short": "1 Leads campaign: prospecting + retargeting ad sets.", "detail": "Advantage+ on, location limited to the service area, 6–15 genuinely different ads per ad set, about 70–80% prospecting and 20–30% retargeting.", "mode": "manual", "owner": "isabella", "tool": "Meta Ads Manager", "when": "Start of month", "feeds": []}, {"id": "ad-review", "title": "Weekly kill / keep / scale", "short": "Written rules, drafted by Claude, signed off by Andres.", "detail": "Kill at 2x target cost per qualified appointment with zero appointments. Scale under target for 7 days by about 20% every 3–4 days. Refresh when frequency passes ~3 or click rate drops 30%.", "mode": "hybrid", "owner": "andres", "tool": "Claude scheduled task + Windsor.ai", "when": "Every Monday", "feeds": []}, {"id": "ad-capi", "title": "Send outcomes to Meta", "short": "Showed / quoted / won go back so Meta learns real jobs.", "detail": "HubSpot stages flow to Meta's Conversions API for CRM. Once there's enough volume, switch the goal to Conversion Leads. Expect 2–3 months to learn.", "mode": "auto", "owner": "andres", "tool": "HubSpot / Zapier → Meta CAPI", "when": "Daily", "feeds": []}, {"id": "ad-report", "title": "15-day client report", "short": "Spend, appointments, cost per appointment, jobs won.", "detail": "What was cut and what we're doubling down on, drafted by Claude and sent by Esteban.", "mode": "hybrid", "owner": "esteban", "tool": "Claude + Windsor.ai + HubSpot", "when": "Every 15 days", "feeds": []}, {"id": "ad-double", "title": "Double down on winners", "short": "Winning concepts get 3 new hooks next month.", "detail": "Winners flow into next month's strategy.", "mode": "manual", "owner": "isabella", "tool": "Notion", "when": "Monthly", "feeds": ["s-strategy"]}]}]}, {"id": "sys6", "code": "6", "name": "Lead management & appointments", "short": "Speed to lead, qualify, book, hand over, bill.", "cadence": "Real time", "stages": [{"id": "st6", "name": "Lead to appointment", "when": "Real time", "steps": [{"id": "a-alert", "title": "Lead alert", "short": "Shared QUO inbox + HubSpot \"Call now\" task.", "detail": "Alerts go to a shared inbox, not anyone's personal phone, so whoever is on duty sees them.", "mode": "auto", "owner": "setter", "tool": "Zapier + HubSpot + QUO", "when": "Instant", "feeds": []}, {"id": "a-call", "title": "Call within 5 minutes", "short": "Business hours. After-hours leads get a call at 8 am.", "detail": "A setter role, not Andres. No calls or texts before 8 am or after 9 pm local time.", "mode": "manual", "owner": "setter", "tool": "QUO app", "when": "Within 5 min", "feeds": []}, {"id": "a-qualify", "title": "Qualify with the script", "short": "Service area, decision-maker, real need, timeline.", "detail": "These are the contract's billing criteria, asked in order.", "mode": "manual", "owner": "setter", "tool": "HubSpot call guide", "when": "On the call", "feeds": []}, {"id": "a-cadence", "title": "Follow-up cadence", "short": "Now, +1 h, next morning, day 3, day 7, then monthly.", "detail": "Tasks and texts are automated; the calls stay human. Most contractor leads are won on the 2nd to 5th try.", "mode": "hybrid", "owner": "setter", "tool": "HubSpot sequence + QUO", "when": "Days 0–7", "feeds": []}, {"id": "a-book", "title": "Book, confirm, remind", "short": "Confirmation text, then reminders 24 h and 2 h before.", "detail": "Booked on the client's calendar. Reminders raise the show rate.", "mode": "hybrid", "owner": "setter", "tool": "Calendly + Zapier → QUO", "when": "On booking", "feeds": []}, {"id": "a-handover", "title": "Hand over to the client", "short": "Lead summary by text and email.", "detail": "Name, address, problem, photos and time, sent automatically.", "mode": "auto", "owner": "client", "tool": "HubSpot workflow", "when": "On booking", "feeds": []}, {"id": "a-log", "title": "Call logged with AI summary", "short": "Recording and summary land in HubSpot.", "detail": "No more typing notes by hand.", "mode": "auto", "owner": "setter", "tool": "QUO → HubSpot integration", "when": "After each call", "feeds": []}, {"id": "a-outcome", "title": "Client logs the outcome", "short": "Showed / quoted / won ($) / lost (why) within 48 h.", "detail": "Reminders repeat until it's logged. This feeds Meta and billing.", "mode": "hybrid", "owner": "client", "tool": "HubSpot link or 3-button text", "when": "Within 48 h", "feeds": ["ad-capi"]}, {"id": "a-bill", "title": "Month-end billing", "short": "Count qualified appointments; 7-day dispute window.", "detail": "$125 per qualified appointment, capped at 20 a month. Claude drafts the report and invoice, Andres approves.", "mode": "hybrid", "owner": "andres", "tool": "HubSpot report + Stripe", "when": "Month end", "feeds": []}]}]}], "flows": [{"from": "sys1", "to": "sys2", "label": "Approved content"}, {"from": "sys2", "to": "sys1", "label": "Post results"}, {"from": "sys2", "to": "sys4", "label": "Top posts"}, {"from": "sys2", "to": "sys6", "label": "DM leads"}, {"from": "sys3", "to": "sys6", "label": "New leads"}, {"from": "sys4", "to": "sys5", "label": "Warm audiences"}, {"from": "sys6", "to": "sys5", "label": "Sales outcomes"}, {"from": "sys5", "to": "sys1", "label": "Winning ads"}]}$json$::jsonb),
  ('abarca-2026-11-ifwz', $json${"name": "ABARCA’S AUTOMOTIVE CARE · November 2026", "kind": "retainer", "package": "authority", "rev": 8, "people": [{"id": "andres", "name": "Andres", "role": "Sales, strategy, growth"}, {"id": "esteban", "name": "Esteban", "role": "Client comms, shooting, ops"}, {"id": "isabella", "name": "Isabella", "role": "PM, planning, QC"}, {"id": "shooter", "name": "Shooter", "role": "On-site capture"}, {"id": "editor", "name": "Editor", "role": "Video edits"}, {"id": "setter", "name": "Setter", "role": "Calls and books leads"}, {"id": "client", "name": "Client", "role": "Approvals, outcomes"}], "packages": [{"id": "visible", "name": "Visible", "price": "$1,500/mo", "blurb": "~6 reels + 6 posts, social management, booking page, review texts.", "systems": ["sys1", "sys2", "sys3"]}, {"id": "authority", "name": "Authority", "price": "$2,500/mo", "blurb": "10 reels, 8 posts, daily stories, local boosting of top content.", "systems": ["sys1", "sys2", "sys3", "sys4"]}, {"id": "growth", "name": "Growth", "price": "$3,500/mo + $125/appt", "blurb": "Authority + 10 ads, testing, appointment setting, 15-day reports.", "systems": ["sys1", "sys2", "sys3", "sys4", "sys5", "sys6"]}], "systems": [{"id": "sys1", "code": "1", "name": "Content & strategy", "short": "From data to approved, ready-to-post content.", "cadence": "Monthly rolling cycle", "stages": [{"id": "st1a", "name": "Strategy & ideas", "when": "Week 4 of M-2", "steps": [{"id": "s-perf", "title": "Pull last month's performance", "short": "Top and bottom posts, hold rate, saves, leads per retainer.", "detail": "On the 1st, a scheduled Claude task reads Metricool and Notion, then writes a Performance Report page on each retainer: top 3 and bottom 3 posts, 3-second hold, saves, shares, profile visits and leads. Isabella reviews it. This runs first because every later step depends on it.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task + Metricool + Notion", "when": "1st of each month", "feeds": ["s-strategy"], "done": true}, {"id": "s-industry", "title": "Industry and competitor scan", "short": "What's going viral in the niche and where competitors are weak.", "detail": "A monthly scheduled run looks at competitors and viral content in the retainer's industry, scores outliers, and lists strengths and weaknesses next to the retainer's own results. Output is saved to the retainer page.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task (web search) or Muse", "when": "Monthly, week 4", "feeds": ["s-strategy"], "done": true}, {"id": "s-persona", "title": "Persona and pain points", "short": "Who buys, what hurts, which words they use.", "detail": "Research the target persona, pain points, objections and the exact words customers use. Sources: the client's Google reviews, competitor reviews, Reddit, and Esteban's call notes. Done at onboarding, then refreshed quarterly. Andres approves.", "mode": "hybrid", "owner": "isabella", "tool": "Claude", "when": "Onboarding + quarterly", "feeds": [], "done": true}, {"id": "s-guidelines", "title": "Brand guidelines", "short": "Video, static, story, caption tone and ad rules per retainer.", "detail": "One guideline page per retainer covering video style, statics, stories, the caption tone prompt, ad rules, and do's and don'ts. It's loaded as knowledge in the retainer's Claude Project so every AI step uses it automatically. Refreshed on the quarterly refresh day.", "mode": "manual", "owner": "isabella", "tool": "Notion + Claude Project", "when": "Quarterly", "feeds": [], "done": false}, {"id": "s-hooks", "title": "Update the Hook Bank", "short": "Add trending hooks and tag which ones performed.", "detail": "A Notion database of hooks with format, industry, source, times used and average 3-second hold. A monthly Claude task adds 20 trending hooks, and Metricool data marks which hooks actually worked for your accounts.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task + Metricool", "when": "Monthly", "feeds": [], "done": false}, {"id": "s-structures", "title": "Video structure library", "short": "Templates: before/after, job walk, myth vs fact, POV, offer.", "detail": "Keep a library of proven video structures with reference links. Refresh it on the same quarterly day as the guidelines.", "mode": "manual", "owner": "isabella", "tool": "Notion", "when": "Quarterly", "feeds": [], "done": false}, {"id": "s-field", "title": "Field ideas from real jobs", "short": "10 grounded ideas per retainer from jobs and client questions.", "detail": "Isabella and Esteban log ideas from real jobs, client FAQs and things heard on site through a Notion form on the phone. Entries land straight in the Idea Bank.", "mode": "hybrid", "owner": "isabella", "tool": "Notion form", "when": "Ongoing", "feeds": [], "done": false}, {"id": "s-strategy", "title": "Monthly strategy (1 page)", "short": "Sales goal, pillar mix, what to double down on and cut.", "detail": "Claude drafts one page per retainer: the month's sales goal, pillar mix, what to double down on and what to cut, the offer to push, and ad tests. Andres approves in the Monday founder meeting, about 5 minutes per retainer.", "mode": "hybrid", "owner": "andres", "tool": "Claude skill: monthly-plan", "when": "Monthly, week 4", "feeds": ["s-ideas"], "done": false}, {"id": "s-ideas", "title": "Generate 40 ideas", "short": "Each tagged with pillar, format, hook, sales job and CTA.", "detail": "The retainer's Claude Project uses the guidelines, reports and Hook Bank as context to produce 40 ideas. Each one is tagged with pillar, format, hook, sales job, CTA and shoot needs. One generator only; other AI tools are optional critics.", "mode": "auto", "owner": "isabella", "tool": "Claude Project (per retainer)", "when": "Monthly, week 4", "feeds": [], "done": false}, {"id": "s-score", "title": "Score and keep the top 25", "short": "Rubric: hook, sales intent, persona fit, shootable, not repeated.", "detail": "Claude scores every idea from 1 to 5 on hook strength, sales intent, persona fit, whether it can be shot in one 3-hour shoot, and whether it repeats the last 90 days. The top 25 are kept.", "mode": "auto", "owner": "isabella", "tool": "Claude Project", "when": "Monthly, week 4", "feeds": [], "done": false}, {"id": "s-pick", "title": "Final pick", "short": "Tier count + 3 backups. The rest go to the Idea Bank.", "detail": "Isabella picks the final pieces: Visible ~12, Authority 18, Growth 18 plus 10 ads, and 3 backups each. Unused ideas are saved in the searchable Idea Bank database, not a Drive folder.", "mode": "manual", "owner": "isabella", "tool": "Notion Idea Bank", "when": "Monthly, week 4", "feeds": ["p-scripts"], "done": false}]}, {"id": "st1b", "name": "Planning", "when": "Week 4 of M-2", "steps": [{"id": "p-scripts", "title": "Scripts and shot lists", "short": "Hook line, beats, B-roll, who's on camera, CTA.", "detail": "Claude drafts a script and shot list for every piece in one run and writes it into each Notion item. Isabella edits.", "mode": "hybrid", "owner": "isabella", "tool": "Claude Project", "when": "Week 4 of M-2", "feeds": [], "done": false}, {"id": "p-stories", "title": "Story plan", "short": "One theme per weekday plus a story capture list.", "detail": "Example frame: Mon crew, Tue job progress, Wed FAQ, Thu review, Fri offer. Ask the client's crew for 3 phone clips a week through an upload link.", "mode": "manual", "owner": "isabella", "tool": "Notion", "when": "Week 4 of M-2", "feeds": [], "done": false}, {"id": "p-props", "title": "Set Notion properties", "short": "Format, type, pillar, sales job, dates, links, status.", "detail": "A Notion template button fills defaults by tier. Every automation reads the same status flow: Idea, Scripted, Shoot booked, Shot, Editing, QC, Client review, Approved, Scheduled, Posted, Analyzed.", "mode": "auto", "owner": "isabella", "tool": "Notion template button", "when": "Week 4 of M-2", "feeds": [], "done": false}, {"id": "p-captions", "title": "Captions in brand tone", "short": "One run fills every caption, with search keywords.", "detail": "The retainer's Claude Project already holds the tone prompt, so one run writes every caption plus keywords for Instagram search and Google Business posts. Isabella checks.", "mode": "hybrid", "owner": "isabella", "tool": "Claude Project", "when": "Week 4 of M-2", "feeds": [], "done": false}, {"id": "p-calendar", "title": "Calendar and shoot days", "short": "Max 3 shoot days per retainer, shooter assigned, post dates.", "detail": "Isabella sets shoot days and post dates in the Notion calendar. Shoot dates sync to the shooter's Google Calendar automatically.", "mode": "hybrid", "owner": "isabella", "tool": "Notion + Zapier → Google Calendar", "when": "Week 4 of M-2", "feeds": ["c-invite"], "done": false}, {"id": "p-brief", "title": "Shoot Brief per shoot day", "short": "Every piece, shots, props, people, access, weather backup.", "detail": "A Claude skill reads every Notion item with that shoot date and builds one brief: pieces, shots, props, people, location, client contact, parking and access, plus a weather backup.", "mode": "auto", "owner": "isabella", "tool": "Claude skill + Notion", "when": "Week 4 of M-2", "feeds": [], "done": false}, {"id": "p-folders", "title": "Create Drive folders", "short": "Retainer / Cycle / RAW and Deliverables / piece.", "detail": "When a piece hits Scripted, an automation creates its RAW and Deliverables folders in Drive and writes the links back to Notion.", "mode": "auto", "owner": "isabella", "tool": "Make or Zapier + Google Drive", "when": "On status: Scripted", "feeds": [], "done": false}, {"id": "p-approve", "title": "Client approves the month plan", "short": "3 business days; silence counts as approval.", "detail": "Esteban sends the list and scripts through the weekly client briefing page. An automatic reminder goes out on day 2. This matches the contract: week 1 is plan approval.", "mode": "hybrid", "owner": "esteban", "tool": "Client briefing page + Zapier reminder", "when": "End of week 4", "feeds": [], "done": false}]}, {"id": "st1c", "name": "Shooting", "when": "Week 1 of M-1", "steps": [{"id": "c-invite", "title": "Shooter gets the invite and brief", "short": "Calendar event with the Shoot Brief link attached.", "detail": "Created automatically from the planning calendar, with the Shoot Brief attached.", "mode": "auto", "owner": "shooter", "tool": "Google Calendar + Notion", "when": "On scheduling", "feeds": [], "done": false}, {"id": "c-confirm", "title": "48-hour confirmation", "short": "Confirm time, access, who's on camera. Check the weather.", "detail": "An auto-text confirms time, site access, who's on camera and that the site is clean. Esteban handles replies and checks the weather for exterior shots.", "mode": "hybrid", "owner": "esteban", "tool": "QUO via Zapier + HubSpot contact", "when": "48 h before", "feeds": [], "done": false}, {"id": "c-shoot", "title": "Shoot the pieces", "short": "Follow the brief order. 3 hook takes for every ad.", "detail": "Shoot in brief order. Every ad concept gets 3 different opening hooks. That's the cheapest A/B test there is.", "mode": "manual", "owner": "shooter", "tool": "Shoot Brief on phone", "when": "Week 1 of M-1", "feeds": [], "done": false}, {"id": "c-broll", "title": "Capture the B-roll library", "short": "Crew, trucks, tools, drone, details, portraits.", "detail": "Ten seconds each of crew working, trucks, tools, drone and exterior shots, details, and team portraits. This fixes missing B-roll and feeds AI generation and ads later.", "mode": "manual", "owner": "shooter", "tool": "Checklist in Shoot Brief", "when": "Every shoot", "feeds": [], "done": false}, {"id": "c-release", "title": "Releases and testimonials", "short": "Signed release for anyone on camera; 30-second testimonial.", "detail": "Get a signed release from any homeowner or crew member on camera. When the customer is happy, ask for a 30-second testimonial. Testimonial ads aren't allowed without consent.", "mode": "hybrid", "owner": "shooter", "tool": "Tally form with signature", "when": "Every shoot", "feeds": [], "done": false}, {"id": "c-upload", "title": "Upload within 24 hours", "short": "Named files in RAW / piece; status flips to Shot.", "detail": "Upload to RAW / piece within 24 hours, named client_piece_take. A new file in the folder sets the Notion status to Shot automatically.", "mode": "hybrid", "owner": "shooter", "tool": "Google Drive + Zapier", "when": "Within 24 h", "feeds": [], "done": false}, {"id": "c-cull", "title": "Culling and selects", "short": "Best takes plus a selects note for the editor.", "detail": "AI pre-selects the best takes from transcripts, and Isabella confirms and writes timestamps and the best hook take for the editor. This was the step eating whole founder days.", "mode": "hybrid", "owner": "isabella", "tool": "Claude skill + Descript transcripts", "when": "Within 48 h", "feeds": ["e-assign"], "done": false}]}, {"id": "st1d", "name": "Editing & QC", "when": "Week 2 of M-1, approved by day 15", "steps": [{"id": "e-assign", "title": "Auto-assign the editor", "short": "Triggered on Shot; style reference already set.", "detail": "When a piece hits Shot, the assigned editor is notified with the style reference and selects note. Editors never wait for direction.", "mode": "auto", "owner": "isabella", "tool": "Notion + Zapier notification", "when": "On status: Shot", "feeds": [], "done": false}, {"id": "e-ai", "title": "AI edit lane", "short": "Captions, cut-downs, resizes and variants by AI.", "detail": "Simple formats go to AI tools: talking-head cuts, captions, cut-downs, ad resizes. Higgsfield handles B-roll and ad variants. Claude writes the edit notes from the guidelines.", "mode": "hybrid", "owner": "isabella", "tool": "Descript / CapCut / Submagic + Higgsfield", "when": "Week 2 of M-1", "feeds": [], "done": false}, {"id": "e-edit", "title": "Editor cuts to the reference", "short": "Hero videos edited by a human to the style reference.", "detail": "Hero reels and anything needing taste are edited by a human editor against the reference video.", "mode": "manual", "owner": "editor", "tool": "CapCut / Premiere", "when": "Week 2 of M-1", "feeds": [], "done": false}, {"id": "e-statics", "title": "Statics and carousels", "short": "Real shoot photo + Canva brand template first.", "detail": "Start from a real job photo and the brand's Canva template. Canva Bulk Create builds the month's carousels from Notion in one go. AI is only for backgrounds, composites and ad variants. Contractors sell trust, so real jobs win.", "mode": "hybrid", "owner": "isabella", "tool": "Canva Bulk Create + Higgsfield + Claude", "when": "Week 2 of M-1", "feeds": [], "done": false}, {"id": "e-copy", "title": "Copy check", "short": "English, spelling, claims and CTA on every file.", "detail": "Claude checks every static, carousel, caption and subtitle for English, spelling, claims and the CTA before QC sees it.", "mode": "auto", "owner": "isabella", "tool": "Claude", "when": "Before QC", "feeds": [], "done": false}, {"id": "e-qc", "title": "QC: 10-point checklist", "short": "Pass = 9/10. Founders spot-check 1 per retainer weekly.", "detail": "Hook in 1.5 s, matches reference, safe zones, captions, brand fonts and colors, audio, licensed music, CTA, length and ratio, no errors. Pass is 9/10. Claude pre-checks text; Isabella checks visuals.", "mode": "hybrid", "owner": "isabella", "tool": "Notion QC score + Claude pre-check", "when": "Week 2 of M-1", "feeds": [], "done": false}, {"id": "e-client", "title": "Client review", "short": "One batch link, max 2 rounds, silence = approved.", "detail": "Esteban sends one link with the whole batch and asks for consolidated feedback. Reminder on day 2, auto-approve on day 4. Maximum 2 revision rounds, per the contract.", "mode": "hybrid", "owner": "esteban", "tool": "Client briefing page + Zapier", "when": "By day 15 of M-1", "feeds": ["m-schedule"], "done": false}, {"id": "e-revise", "title": "Batched revisions", "short": "Fixes done once a week, not as a daily drip.", "detail": "Revisions are batched once a week and the revision count is logged on the piece. The editor scorecard tracks it monthly.", "mode": "manual", "owner": "editor", "tool": "Notion", "when": "Weekly", "feeds": [], "done": false}]}], "date": ""}, {"id": "sys2", "code": "2", "name": "Social media management", "short": "Scheduling, Google Business, stories, comment-to-lead.", "cadence": "Daily automation", "stages": [{"id": "st2", "name": "Scheduling & publishing", "when": "Daily", "steps": [{"id": "m-schedule", "title": "Auto-schedule approved posts", "short": "At the best time per account; status flips to Scheduled.", "detail": "A daily Claude task finds every piece marked Approved, schedules it in Metricool at the best time for that account, flips Notion to Scheduled and saves the post ID.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task + Metricool + Notion", "when": "Daily", "feeds": [], "done": false}, {"id": "m-posted", "title": "Mark as Posted", "short": "Closes the loop Metricool doesn't close itself.", "detail": "The same daily task checks Metricool and flips live posts to Posted in Notion.", "mode": "auto", "owner": "isabella", "tool": "Claude scheduled task", "when": "Daily", "feeds": [], "done": false}, {"id": "m-gbp", "title": "Google Business posts", "short": "1–2 a week: recent job, photo, service, city.", "detail": "Every plan includes Google Business Profile. Repurpose the week's best post as a GBP post.", "mode": "auto", "owner": "isabella", "tool": "Metricool (GBP)", "when": "Weekly", "feeds": [], "done": false}, {"id": "m-stories", "title": "Daily stories", "short": "From the story plan and crew clips.", "detail": "Post daily stories from the story plan and the client crew's phone clips.", "mode": "hybrid", "owner": "isabella", "tool": "Metricool or native app", 